{"code": "import requests
import json

orcid_ids = [
    "0000-0003-0396-0333",  # Manuela Nagel
    "0000-0002-2605-6569",  # Tatjana Gavrilenko
    "0000-0001-6102-7846",  # John Bamberg
    "0000-0002-0209-2784",  # David Ellis
    "0000-0002-1053-2030",  # Peter Giovannini
]

names = {
    "0000-0003-0396-0333": "Manuela Nagel",
    "0000-0002-2605-6569": "Tatjana Gavrilenko",
    "0000-0001-6102-7846": "John Bamberg",
    "0000-0002-0209-2784": "David Ellis",
    "0000-0002-1053-2030": "Peter Giovannini",
}

results = {}

for orcid in orcid_ids:
    url = f"https://pub.orcid.org/v2.1/{orcid}/works"
    headers = {"Accept": "application/json"}
    response = requests.get(url, headers=headers)

    if response.status_code == 200:
        data = response.json()
        works = data.get("group", [])

        pre_2020_count = 0
        total_count = len(works)

        for work in works:
            # Each work group has a publication-date
            pub_date = work.get("work-summary", [{}])[0].get("publication-date", {}) if work.get("work-summary") else {}
            if not pub_date:
                # Try to get from the work group level
                pub_date = work.get("publication-date", {})

            year = pub_date.get("year", {}).get("value", None)
            if year is not None:
                year_int = int(year)
                if year_int < 2020:
                    pre_2020_count += 1

        results[orcid] = {
            "name": names[orcid],
            "total": total_count,
            "pre_2020": pre_2020_count
        }
        print(f"{names[orcid]} ({orcid}): total={total_count}, pre-2020={pre_2020_count}")
    else:
        results[orcid] = {"name": names[orcid], "total": 0, "pre_2020": 0}
        print(f"{names[orcid]} ({orcid}): error status {response.status_code}")

# Calculate average
total_pre_2020 = sum(r["pre_2020"] for r in results.values())
num_researchers = len(results)
average = total_pre_2020 / num_researchers

print(f"\nTotal pre-2020 works: {total_pre_2020}")
print(f"Number of researchers: {num_researchers}")
print(f"Average pre-2020 works: {average}")"}
